use builtin::*;
use builtin_macros::*;
use verus::*;

verus! {

/// rsplit: For each string in a,
/// perform a right-split on sep at most maxsplit times.
///
/// Properties:
/// - sep is non-empty.
/// - output length == input length.
/// - each inner vector is non-empty.
/// - if maxsplit == 0, each inner result is a single element equal to original string.
/// - parts count ≤ maxsplit + 1.
/// - empty input string splits to single empty string.
fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> 
  requires sep.len() > 0
  ensures |res| res.len() == a.len()
  ensures forall|i: int| 0 <= i && i < res.len() ==> res[i].len() >= 1
  ensures forall|i: int| 0 <= i && i < res.len() ==>
    if maxsplit == 0 {
      res[i].len() == 1 && res[i][0] == a[i]
    } else {
      res[i].len() <= maxsplit as int + 1
    }
  ensures forall|i: int| 0 <= i && i < res.len() ==>
    (a[i].len() == 0 ==> res[i].len() == 1 && res[i][0] == "")
{
    // Helper function to perform right split on a single string.
    // Implements rsplit behavior with maxsplit and sep non-empty.
    // Using a loop to find sep occurrences from right, up to maxsplit times.
    fn rsplit_once(s: &String, sep: &String, maxsplit: u8) -> Vec<String>
      requires sep.len() > 0
      ensures |result: &Vec<String>| result.len() >= 1 && result.len() <= maxsplit as int + 1
      ensures if maxsplit == 0 { result.len() == 1 && result[0] == *s } else true
      ensures s.len() == 0 ==> (result.len() == 1 && result[0] == "")
    {
        if maxsplit == 0 {
            vec![s.clone()]
        } else if s.len() == 0 {
            // empty string => single empty part
            vec![String::from_str("")]
        } else {
            let mut parts: Vec<String> = Vec::new();

            // positions of splits from right
            let mut splits = vec![];

            // current search end index (exclusive)
            let mut end = s.len();

            // count of splits found
            let mut count: u8 = 0;

            // Loop to find up to maxsplit occurrences of sep from right
            while count < maxsplit {
                // find last occurrence of sep before "end"
                // Verus string API is limited, so define a helper function to find from right:
                // Since sep non-empty, and s.len() finite, can do loop from end-1 down to 0
                
                let mut found: Option<int> = None; // index of start of sep
                let sep_len = sep.len();

                let mut idx: int = end as int - sep_len as int;
                while idx >= 0 {
                    let maybe_sub = s.subslice(idx as nat, idx as nat + sep_len);
                    if maybe_sub == *sep {
                        found = Some(idx);
                        break;
                    }
                    idx -= 1;
                }

                match found {
                    None => {
                        break;
                    }
                    Some(pos) => {
                        // record this split position
                        splits.push(pos as nat);
                        end = pos;
                        count += 1;
                    }
                }
            }

            // Now, build parts from splits found, starting from left-most split
            splits.reverse();

            let mut start: nat = 0;
            for split_pos in splits.iter() {
                // part is s[start .. split_pos]
                let part = s.subslice(start, *split_pos);
                parts.push(part);
                // skip sep itself for next start
                start = *split_pos + sep_len;
            }
            // last part from last split to end of string
            let last_part = s.subslice(start, s.len());
            parts.push(last_part);

            if parts.len() == 0 {
                // fallback (should not happen), return s itself
                vec![s.clone()]
            } else {
                parts
            }
        }
    }

    let mut res: Vec<Vec<String>> = Vec::new();
    let mut i: int = 0;
    while i < a.len() {
        invariant 0 <= i && i <= a.len();
        let parts = rsplit_once(&a[i], &sep, maxsplit);
        // parts at least length 1 always by rsplit_once ensures
        res.push(parts);
        i += 1;
    }
    res
}

}